import json,os,subprocess,re,socket,urllib.request,urllib.error
from pathlib import Path
def capture(a,timeout=9):
 try:
  p=subprocess.run(a,capture_output=True,text=True,timeout=timeout)
  return p.returncode,p.stdout.strip()
 except Exception as e:return -1,type(e).__name__
def ping(port,path):
 try:
  with urllib.request.urlopen('http://127.0.0.1:'+str(port)+path,timeout=8) as a:return a.getcode()
 except urllib.error.HTTPError as e:return e.code
 except Exception:return 'not_http'
r={'service_baseline':{},'env_privates':{},'units':{}}
for name in ('fadego-staging','pink-iptv-backend','pink-vpn'):
 rc,act=capture(['systemctl','is-active',name])
 c,txt=capture(['systemctl','show',name,'-p','ExecStart','--value'])
 found=re.findall(r'(?:--port(?:=|\s+)|-p\s+)([0-9]{2,5})(?=\s|;|$)',txt)
 r['service_baseline'][name]={'active':act,'unit_start_port':found[-1] if found else None,'main_pid':capture(['systemctl','show',name,'--property=MainPID','--value'])[1].isdigit()}
 if name=='fadego-staging':
  r['service_baseline'][name]['http_3100']=ping(3100,'/')
 if name=='pink-iptv-backend' and found:
  r['service_baseline'][name]['http_root']=ping(found[-1],'/')
  r['service_baseline'][name]['http_health']=ping(found[-1],'/health')
 path=Path('/etc/systemd/system')/(name+'.service')
 r['units'][name]={'regular':path.is_file() and not path.is_symlink(),'exists':path.exists(),'mode':oct(path.stat().st_mode&0o777) if path.is_file() else None}
for name in ('fadego','pink-iptv'):
 for f in ('app.env','send-closed.env') if name=='fadego' else ('backend.env','secrets.env','vpn.env'):
  p=Path('/srv/projects')/name/'private/systemd-env'/f
  r['env_privates'][name+'/'+f]={'exists':p.is_file(),'mode':oct(p.stat().st_mode&0o777) if p.is_file() else None}
print(json.dumps(r,separators=(',',':')))
